from bisect import bisect_left

def solve(nums):
    if nums is None:
        return 0
    tails = []
    for x in nums:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

