def solve(grid):
    """Count islands of 1s in a possibly ragged grid.
    Connectivity is orthogonal (up, down, left, right). Handles empty grid
    and rows of varying lengths.
    """
    if not grid:
        return 0
    n = len(grid)
    # visited mirrors grid shape
    visited = [ [False]*len(row) for row in grid ]
    def neighbors(i, j):
        # up
        if i > 0 and j < len(grid[i-1]):
            yield i-1, j
        # down
        if i+1 < n and j < len(grid[i+1]):
            yield i+1, j
        # left
        if j > 0:
            yield i, j-1
        # right
        if j+1 < len(grid[i]):
            yield i, j+1
    def bfs(start_i, start_j):
        stack = [(start_i, start_j)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for ni, nj in neighbors(i, j):
                if not visited[ni][nj] and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                islands += 1
                bfs(i, j)
    return islands

